// 翻后 Micro-LUT 预解策略矩阵资产 (Phase 4 - Micro-LUT)
// 自动由 scripts/build_postflop_lut.mjs 编译生成
// 规格：28 牌面簇 × 24 手牌子桶 × 4 SPR × 4 尺度 × 6 上下文 = 64,512 决策行
// 内存常驻: ~280KB Uint8Array，查询复杂度 O(1)，纯客户端零网络请求

(function(global) {
  const METADATA = {
    version: '2.90-alpha',
    clusters: 28,
    subBuckets: 24,
    sprTiers: 4,
    sizeTiers: 4,
    contexts: 6,
    totalRows: 64512,
    policyBytes: 258048,
    flopMapBytes: 22100
  };

  const BASE64_FLOP_CLUSTER_MAP = "";
  const BASE64_POSTFLOP_POLICY_LUT = "";

  // 解码 Base64 为 Uint8Array
  function decodeBase64ToUint8Array(base64) {
    if (typeof Buffer !== 'undefined') {
      return new Uint8Array(Buffer.from(base64, 'base64'));
    }
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  }

  const FLOP_CLUSTER_MAP = decodeBase64ToUint8Array(BASE64_FLOP_CLUSTER_MAP);
  const POSTFLOP_POLICY_LUT = decodeBase64ToUint8Array(BASE64_POSTFLOP_POLICY_LUT);

  /**
   * 依据 Flop Colex 索引快速查出 28 牌面簇 ID (0..27)
   */
  function lookupFlopClusterByIdx(flopIdx) {
    if (flopIdx < 0 || flopIdx >= FLOP_CLUSTER_MAP.length) return 0;
    return FLOP_CLUSTER_MAP[flopIdx];
  }

  /**
   * 依据 5 维坐标 O(1) 检索四动作量化字节 [q0, q1, q2, q3]
   */
  function lookupPostflopLutBytes(clusterId, subBucketId, sprTier, sizeTier, contextId) {
    const cl = Math.max(0, Math.min(27, clusterId || 0));
    const bk = Math.max(0, Math.min(23, subBucketId || 0));
    const spr = Math.max(0, Math.min(3, sprTier || 0));
    const sz = Math.max(0, Math.min(3, sizeTier || 0));
    const ctx = Math.max(0, Math.min(5, contextId || 0));

    const rowIndex = ((((cl * 24 + bk) * 4 + spr) * 4 + sz) * 6 + ctx);
    const offset = rowIndex * 4;

    return [
      POSTFLOP_POLICY_LUT[offset],
      POSTFLOP_POLICY_LUT[offset + 1],
      POSTFLOP_POLICY_LUT[offset + 2],
      POSTFLOP_POLICY_LUT[offset + 3]
    ];
  }

  global.POSTFLOP_LUT_METADATA = METADATA;
  global.FLOP_CLUSTER_MAP = FLOP_CLUSTER_MAP;
  global.POSTFLOP_POLICY_LUT = POSTFLOP_POLICY_LUT;
  global.lookupFlopClusterByIdx = lookupFlopClusterByIdx;
  global.lookupPostflopLutBytes = lookupPostflopLutBytes;

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
      METADATA,
      FLOP_CLUSTER_MAP,
      POSTFLOP_POLICY_LUT,
      lookupFlopClusterByIdx,
      lookupPostflopLutBytes
    };
    exports.METADATA = METADATA;
    exports.FLOP_CLUSTER_MAP = FLOP_CLUSTER_MAP;
    exports.POSTFLOP_POLICY_LUT = POSTFLOP_POLICY_LUT;
    exports.lookupFlopClusterByIdx = lookupFlopClusterByIdx;
    exports.lookupPostflopLutBytes = lookupPostflopLutBytes;
  }
})(typeof window !== 'undefined' ? window : (typeof globalThis !== 'undefined' ? globalThis : this));
